// src/components/Dolar.js
import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Line } from 'react-chartjs-2';
import Chart from 'chart.js/auto';

const Dolar = () => {
    const [data, setData] = useState([]);
    const [labels, setLabels] = useState([]);
    
    // Define las URL de la API para las predicciones
    const urlProphet = 'http://localhost:8000/prophet-predictions'; // Asegúrate de que este sea el URL correcto
    const urlARMA = 'http://localhost:8000/arma-predictions'; // Asegúrate de que este sea el URL correcto

    useEffect(() => {
        const fetchData = async () => {
            try {
                // Llama a la API de Prophet
                const responseProphet = await axios.get(urlProphet);
                const prophetData = responseProphet.data;
                const prophetValues = prophetData.predictions;
                const prophetDates = prophetData.dates;

                // Llama a la API de ARMA
                const responseARMA = await axios.get(urlARMA);
                const armaData = responseARMA.data;
                const armaValues = armaData.predictions;
                const armaDates = armaData.dates;

                // Combina los datos de ambas predicciones si es necesario
                const combinedValues = [...prophetValues, ...armaValues];
                const combinedDates = [...prophetDates, ...armaDates];

                // Establece los datos en el estado
                setData(combinedValues);
                setLabels(combinedDates);
            } catch (error) {
                console.error("Error al obtener los datos de predicción:", error);
            }
        };

        fetchData();
    }, []);
    
    const chartData = {
        labels: labels,
        datasets: [
            {
                label: 'Predicción del Dólar (MXN)',
                data: data,
                borderColor: 'rgba(75,192,192,1)',
                backgroundColor: 'rgba(75,192,192,0.2)',
                fill: true,
            },
        ],
    };

    return (
        <div>
            <h1>Predicción del Dólar en MXN</h1>
            {data.length > 0 ? (
                <Line data={chartData} />
            ) : (
                <p>Cargando datos...</p>
            )}
        </div>
    );
};

export default Dolar;
